*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fbf9f4;color:#203a35;font:16px/1.6 Arial,sans-serif}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}img{display:block;width:100%;object-fit:cover}main{overflow:hidden}.samplebar{background:#deebe7;padding:8px 5%;display:flex;justify-content:space-between;font-size:11px;gap:15px}.samplebar a{text-decoration:underline}nav{padding:23px 5%;display:flex;align-items:center;gap:35px;border-bottom:1px solid #dce3dc}.brand{margin-right:auto;font:700 21px/1.15 Georgia,serif}.brand small{display:block;font:9px Arial;letter-spacing:2px;margin-top:7px}.navlinks{display:flex;gap:22px;font-size:12px;align-items:center}.button{background:#176756;color:white;border:0;padding:13px 21px;border-radius:4px;display:inline-flex;align-items:center;gap:18px;font-size:13px;font-weight:700}.button:hover{background:#124e41}.hero{display:grid;grid-template-columns:1.04fr 1fr;max-width:1440px;margin:auto;min-height:610px}.intro{padding:70px 8% 55px 10%}.eyebrow{font-size:10px;font-weight:bold;letter-spacing:2px;color:#60776b;text-transform:uppercase}.intro h1{font:normal clamp(42px,4.5vw,67px)/1.06 Georgia,serif;letter-spacing:-2px;margin:26px 0}.intro h1 em{color:#287a63;font-weight:normal}.intro p{color:#66766b;font-size:15px;max-width:380px;margin:25px 0 30px}.hero-image{position:relative;min-height:490px}.hero-image img{height:100%;position:absolute;inset:0;object-position:55% center}.hero-caption{position:absolute;left:28px;bottom:28px;background:#fcfbf2eb;padding:17px 22px;max-width:270px;font:19px/1.35 Georgia,serif}.hero-caption small{display:block;font:10px Arial;letter-spacing:1px;margin-top:10px;color:#577b67}.trust{background:#edf0e6;border-block:1px solid #dce3d6;display:grid;grid-template-columns:repeat(3,1fr);padding:24px 7%;gap:25px}.trust strong{font:23px Georgia,serif;display:block}.trust p{margin:6px 0 0;font-size:12px;color:#647265}.section{max-width:1240px;margin:auto;padding:74px 40px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:25px;margin-bottom:28px}h2{font:normal 39px/1.15 Georgia,serif;margin:13px 0}h3{font:normal 24px/1.2 Georgia,serif;margin:18px 0 10px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filters button,.amounts button,.frequencies button{border:1px solid #d2dccc;background:transparent;padding:8px 14px;border-radius:3px;color:#385a47;font-size:12px}.filters button[aria-pressed=true],.amounts button[aria-pressed=true],.frequencies button[aria-pressed=true]{background:#245b48;color:white;border-color:#245b48}.projects{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.card[hidden]{display:none}.card{background:white;border:1px solid #dce3d6;border-radius:5px;overflow:hidden}.card img{height:210px}.card .copy{padding:4px 24px 25px}.card p{font-size:13px;color:#657266}.card a{font-size:12px;font-weight:bold;color:#296248}.donate{margin:0 5% 70px;display:grid;grid-template-columns:1fr 1fr;gap:60px;background:#e7edde;border-radius:8px;padding:52px 7%;align-items:center}.donate p{font-size:14px;color:#60725e;max-width:380px}.donate-box{background:#fbfcf6;border:1px solid #d1dbca;padding:27px;border-radius:5px}.frequencies{display:flex;gap:8px;margin:12px 0 20px}.amounts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.amounts button{font-size:21px;padding:16px 4px}.selection{font-size:13px;margin:17px 0 20px;min-height:20px}.donate-box .button{width:100%;justify-content:center}.note{font-size:10px!important;line-height:1.4;color:#768570!important}.about{border-top:1px solid #dce3d6;padding:30px 7%;display:flex;justify-content:space-between;gap:45px}.about p{font-size:12px;max-width:540px;color:#627465;margin:0}footer{border-top:1px solid #dce3d6;padding:22px 5%;font-size:10px;color:#748477;display:flex;justify-content:space-between;gap:20px}footer a{text-decoration:underline}@media(max-width:940px){nav{gap:20px}.navlinks{gap:12px;font-size:10px}.hero{min-height:540px}.intro{padding:55px 8%}.projects{gap:14px}.card .copy{padding:4px 18px 22px}.donate{gap:30px;padding:35px 5%}}@media(max-width:700px){.samplebar{font-size:9px}nav{padding:20px 5%;flex-wrap:wrap;gap:18px}.brand{font-size:20px}.navlinks{width:100%;justify-content:space-between;gap:9px;flex-wrap:wrap}.navlinks .button{padding:8px 12px;font-size:10px}.hero{grid-template-columns:1fr}.intro{padding:40px 6%}.intro h1{font-size:49px}.intro p{font-size:14px}.hero-image{min-height:330px;order:-1}.hero-caption{font-size:17px;bottom:18px;left:20px;padding:12px 18px;max-width:220px}.trust{padding:24px 6%;gap:15px}.trust strong{font-size:20px}.trust p{font-size:10px}.section{padding:45px 6%}.section-head{display:block}h2{font-size:34px}.filters{margin-top:18px}.projects{grid-template-columns:1fr}.card img{height:230px}.donate{grid-template-columns:1fr;margin:0 5% 35px;padding:30px 6%;gap:15px}.about,footer{flex-direction:column;gap:16px}}

.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}

document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
  document.querySelectorAll('[data-filter]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));
  document.querySelectorAll('.card').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter);
}));
let amount='25',frequency='einmalig';
function updateSelection(){document.getElementById('donation-selection').textContent='Deine Auswahl: '+amount+' € '+frequency+'.';}
for(const type of ['amount','frequency']){
 document.querySelectorAll('[data-'+type+']').forEach(button=>button.addEventListener('click',()=>{
   document.querySelectorAll('[data-'+type+']').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));
   if(type==='amount')amount=button.dataset.amount;else frequency=button.dataset.frequency;
   updateSelection();
 }));
}
